      out.write("                    const dept = ($(this).data('dept') || '').toString().toUpperCase();\n");
      out.write("                    const sem = ($(this).data('semester') || '').toString().toUpperCase();\n");
      out.write("\n");
      out.write("                    const matchesSearch = !query || id.includes(query) || ('#' + id).includes(query) || uid.includes(query) || name.includes(query) || username.includes(query) || email.includes(query) || phone.includes(query) || dept.toLowerCase().includes(query) || sem.toLowerCase().includes(query);\n");
      out.write("                    const matchesDept = (selectedDept === 'ALL') || (dept === selectedDept);\n");
      out.write("                    const matchesSemester = (selectedSemester === 'ALL') || (sem === selectedSemester.toUpperCase());\n");
      out.write("\n");
      out.write("                    if (matchesSearch && matchesDept && matchesSemester) {\n");
      out.write("                        $(this).show();\n");
      out.write("                        visibleCount++;\n");
      out.write("                    } else {\n");
      out.write("                        $(this).hide();\n");
      out.write("                    }\n");
      out.write("                });\n");
      out.write("\n");
      out.write("                const colSpan = isAdmin ? 10 : 8;\n");
      out.write("                if (visibleCount === 0 && $('.student-item').length > 0) {\n");
      out.write("                    if ($('#noMatchRow').length === 0) {\n");
      out.write("                        $('#studentTableBody').append('<tr id=\"noMatchRow\"><td colspan=\"' + colSpan + '\" class=\"text-center py-4 text-muted\"><i class=\"bi bi-search fs-3 d-block mb-1\"></i>No students matching your filter criteria.</td></tr>');\n");
      out.write("                    }\n");
      out.write("                } else {\n");
      out.write("                    $('#noMatchRow').remove();\n");
      out.write("                }\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            $('#searchInput').on('input keyup', applyFilters);\n");
      out.write("            $('#deptFilter').on('change', applyFilters);\n");
      out.write("            $('#semesterFilter').on('change', applyFilters);\n");
      out.write("\n");
      out.write("            // ==================== Academic Results Handlers ====================\n");
      out.write("            $(document).on('click', '.btn-results', function (e) {\n");
      out.write("                e.preventDefault();\n");
      out.write("                const id = $(this).data('id');\n");
      out.write("                const uid = $(this).data('uid');\n");
      out.write("                const name = $(this).data('name');\n");
      out.write("                const dept = $(this).data('dept');\n");
      out.write("                const semester = $(this).data('semester');\n");
      out.write("                openResultsModal(id, uid, name, dept, semester);\n");
      out.write("            });\n");
      out.write("\n");
      out.write("            function reloadResultsModal() {\n");
      out.write("                if (!currentResultsStudentUid && !currentResultsStudentId) return;\n");
      out.write("                openResultsModal(\n");
      out.write("                    currentResultsStudentId,\n");
      out.write("                    currentResultsStudentUid,\n");
      out.write("                    $('#modalStudentName').text(),\n");
      out.write("                    $('#modalStudentDept').text(),\n");
      out.write("                    $('#modalStudentSem').text()\n");
      out.write("                );\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            function openResultsModal(id, uid, fallbackName, fallbackDept, fallbackSem) {\n");
      out.write("                if (!uid && typeof id === 'string' && id.includes('-')) {\n");
      out.write("                    uid = id;\n");
      out.write("                    id = null;\n");
      out.write("                }\n");
      out.write("                if (id !== undefined && id !== null && id !== '') {\n");
      out.write("                    currentResultsStudentId = id;\n");
      out.write("                }\n");
      out.write("                if (uid !== undefined && uid !== null && uid !== '') {\n");
      out.write("                    currentResultsStudentUid = uid;\n");
      out.write("                }\n");
      out.write("\n");
      out.write("                const requestId = currentResultsStudentId;\n");
      out.write("                const requestUid = currentResultsStudentUid;\n");
      out.write("\n");
      out.write("                $('#modalStudentName').text(fallbackName || '-');\n");
      out.write("                $('#modalStudentUid').text(requestId ? ('Student ID: #' + requestId) : (requestUid ? ('ID: ' + requestUid) : '-'));\n");
      out.write("                $('#modalStudentDept').text(fallbackDept || '-');\n");
      out.write("                const initialSem = (fallbackSem || 'FALL 2025').trim();\n");
      out.write("                $('#modalStudentSem').text(initialSem);\n");
      out.write("                $('#modalSemDuration').html('<i class=\"bi bi-clock-history me-1\"></i>' + getSemesterDurationText(initialSem));\n");
      out.write("                $('#modalCgpaDisplay').text('0.00');\n");
      out.write("                $('#footerCgpa').text('0.00');\n");
      out.write("                $('#modalPublishStatusBadge').removeClass('bg-success bg-warning bg-secondary bg-info text-white text-dark')\n");
      out.write("                    .addClass('bg-secondary text-white').text('Loading...');\n");
      out.write("\n");
      out.write("                $('#resultsLoading').removeClass('d-none');\n");
      out.write("                $('#resultsTableContainer').addClass('d-none');\n");
      out.write("                $('#noResultsAlert').addClass('d-none');\n");
      out.write("\n");
      out.write("                if (resultsModal) resultsModal.show();\n");
      out.write("\n");
      out.write("                $.ajax({\n");
      out.write("                    url: contextPath + '/api/students',\n");
      out.write("                    type: 'POST',\n");
      out.write("                    contentType: 'application/json; charset=UTF-8',\n");
      out.write("                    data: JSON.stringify({ action: 'get_results', id: requestId, uid: requestUid }),\n");
      out.write("                    headers: { 'X-Requested-With': 'XMLHttpRequest' },\n");
      out.write("                    success: function (res) {\n");
      out.write("                        $('#resultsLoading').addClass('d-none');\n");
      out.write("                        if (res.success) {\n");
      out.write("                            let stuSem = initialSem;\n");
      out.write("                            if (res.student) {\n");
      out.write("                                $('#modalStudentName').text(res.student.name || fallbackName);\n");
      out.write("                                $('#modalStudentUid').text(res.student.id ? ('Student ID: #' + res.student.id) : (res.student.uid ? ('ID: ' + res.student.uid) : '-'));\n");
      out.write("                                $('#modalStudentDept').text(res.student.department || fallbackDept);\n");
      out.write("                                stuSem = (res.student.semester || fallbackSem || 'FALL 2025').trim();\n");
      out.write("                                $('#modalStudentSem').text(stuSem);\n");
      out.write("                            }\n");
      out.write("\n");
      out.write("                            if (res.currentSemesterDuration) {\n");
      out.write("                                $('#modalSemDuration').html('<i class=\"bi bi-clock-history me-1\"></i>' + escapeHtml(res.currentSemesterDuration));\n");
      out.write("                            } else {\n");
      out.write("                                $('#modalSemDuration').html('<i class=\"bi bi-clock-history me-1\"></i>' + getSemesterDurationText(stuSem));\n");
      out.write("                            }\n");
      out.write("\n");
      out.write("                            const resultsList = res.results || [];\n");
      out.write("                            currentResultsList = resultsList;\n");
      out.write("                            const canEdit = res.canEdit && isAdmin;\n");
      out.write("\n");
      out.write("                            if (!resultsList || resultsList.length === 0) {\n");
      out.write("                                if (!isAdmin) {\n");
      out.write("                                    $('#noResultsAlert').removeClass('d-none');\n");
      out.write("                                    $('#modalPublishStatusBadge').removeClass('bg-secondary bg-success text-white').addClass('bg-warning text-dark').text('Not Published');\n");
      out.write("                                } else {\n");
      out.write("                                    $('#resultsTableContainer').removeClass('d-none');\n");
      out.write("                                    $('#resultsTableBody').html('<tr><td colspan=\"' + (isAdmin ? 9 : 8) + '\" class=\"text-center py-4 text-muted\">No official curriculum courses found for department ' + escapeHtml(res.student ? res.student.department : '') + '</td></tr>');\n");
      out.write("                                }\n");
      out.write("                                return;\n");
      out.write("                            }\n");
      out.write("\n");
      out.write("                            // Determine overall publish state based on evaluated courses\n");
      out.write("                            let anyEvaluated = false;\n");
      out.write("                            let anyPublished = false;\n");
      out.write("                            let allEvaluatedPublished = true;\n");
      out.write("\n");
      out.write("                            resultsList.forEach(function (item) {\n");
      out.write("                                if (item.evaluated) {\n");
      out.write("                                    anyEvaluated = true;\n");
      out.write("                                    if (item.published) {\n");
      out.write("                                        anyPublished = true;\n");
      out.write("                                    } else {\n");
      out.write("                                        allEvaluatedPublished = false;\n");
      out.write("                                    }\n");
      out.write("                                }\n");
      out.write("                            });\n");
      out.write("\n");
      out.write("                            if (anyEvaluated && allEvaluatedPublished) {\n");
      out.write("                                $('#modalPublishStatusBadge').removeClass('bg-secondary bg-warning bg-info text-dark').addClass('bg-success text-white').html('<i class=\"bi bi-check-circle-fill me-1\"></i>Published');\n");
      out.write("                            } else if (anyPublished) {\n");
      out.write("                                $('#modalPublishStatusBadge').removeClass('bg-secondary bg-success text-white bg-warning text-dark').addClass('bg-info text-white').html('<i class=\"bi bi-clock-history me-1\"></i>Partially Published');\n");
      out.write("                            } else if (anyEvaluated) {\n");
      out.write("                                $('#modalPublishStatusBadge').removeClass('bg-secondary bg-success text-white bg-info').addClass('bg-warning text-dark').html('<i class=\"bi bi-exclamation-circle me-1\"></i>Unpublished');\n");
      out.write("                            } else {\n");
      out.write("                                $('#modalPublishStatusBadge').removeClass('bg-success bg-info bg-warning text-white text-dark').addClass('bg-secondary text-white').html('<i class=\"bi bi-dash-circle me-1\"></i>Not Evaluated');\n");
      out.write("                            }\n");
      out.write("\n");
      out.write("                            // Build options for modal semester filter combo boxes\n");
      out.write("                            let semFilterOpts = '<option value=\"ALL\">All Semesters</option>';\n");
      out.write("                            const studentFoundSemesters = new Set();\n");
      out.write("                            resultsList.forEach(function (item) {\n");
      out.write("                                if (item.semester && item.semester.trim()) {\n");
      out.write("                                    studentFoundSemesters.add(item.semester.trim().toUpperCase());\n");
      out.write("                                }\n");
      out.write("                            });\n");
      out.write("                            studentFoundSemesters.forEach(function (s) {\n");
      out.write("                                semFilterOpts += '<option value=\"' + s + '\">' + s + '</option>';\n");
      out.write("                            });\n");
      out.write("                            availableSemestersList.forEach(function (s) {\n");
      out.write("                                if (!studentFoundSemesters.has(s.toUpperCase())) {\n");
      out.write("                                    semFilterOpts += '<option value=\"' + s + '\">' + s + '</option>';\n");
      out.write("                                }\n");
      out.write("                            });\n");
      out.write("                            $('#modalCourseSemesterFilter').html(semFilterOpts).val('ALL');\n");
      out.write("\n");
      out.write("                            renderResultsTable(resultsList, canEdit);\n");
      out.write("                            $('#resultsTableContainer').removeClass('d-none');\n");
      out.write("                        } else {\n");
      out.write("                            showToast('danger', res.message || 'Failed to load student results.');\n");
      out.write("                            if (resultsModal) resultsModal.hide();\n");
      out.write("                        }\n");
      out.write("                    },\n");
      out.write("                    error: function (xhr) {\n");
      out.write("                        $('#resultsLoading').addClass('d-none');\n");
      out.write("                        let errMsg = 'Error loading course results.';\n");
      out.write("                        try {\n");
      out.write("                            const errData = JSON.parse(xhr.responseText);\n");
      out.write("                            if (errData && errData.message) errMsg = errData.message;\n");
      out.write("                        } catch (e) {}\n");
      out.write("                        showToast('danger', errMsg);\n");
      out.write("                        if (resultsModal) resultsModal.hide();\n");
      out.write("                    }\n");
      out.write("                });\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            function renderResultsTable(results, canEdit) {\n");
      out.write("                const $tbody = $('#resultsTableBody');\n");
      out.write("                $tbody.empty();\n");
      out.write("\n");
      out.write("                let totalCredits = 0;\n");
      out.write("                let weightedPoints = 0;\n");
      out.write("                let evaluatedCount = 0;\n");
      out.write("                let unevaluatedCount = 0;\n");
      out.write("                const activeOverallSem = $('#modalStudentSem').text() || 'FALL 2025';\n");
      out.write("\n");
      out.write("                results.forEach(function (r, index) {\n");
      out.write("                    const credits = parseFloat(r.creditHours) || 3.0;\n");
      out.write("                    const isEvaluated = (r.evaluated === true);\n");
      out.write("                    const hasMarks = (isEvaluated && r.marks !== null && r.marks !== undefined && r.marks >= 0);\n");
      out.write("                    const marks = hasMarks ? parseFloat(r.marks) : '';\n");
      out.write("                    const gp = hasMarks ? getGradePoint(marks) : 0.00;\n");
      out.write("                    const letter = hasMarks ? getLetterGrade(marks) : '-';\n");
      out.write("                    const badgeClass = hasMarks ? getGradeBadgeClass(letter) : 'badge bg-secondary-subtle text-secondary';\n");
      out.write("                    const isPub = (isEvaluated && r.published === true);\n");
      out.write("                    const courseSem = (r.semester && r.semester.trim()) ? r.semester.trim() : activeOverallSem;\n");
      out.write("\n");
      out.write("                    if (isEvaluated && hasMarks) {\n");
      out.write("                        weightedPoints += (gp * credits);\n");
      out.write("                        totalCredits += credits;\n");
      out.write("                        evaluatedCount++;\n");
      out.write("                    } else {\n");
      out.write("                        unevaluatedCount++;\n");
      out.write("                    }\n");
      out.write("\n");
      out.write("                    let marksHtml = '';\n");
      out.write("                    if (canEdit) {\n");
      out.write("                        marksHtml = '<input type=\"number\" min=\"0\" max=\"100\" step=\"0.5\" ' +\n");
      out.write("                            'class=\"form-control form-control-sm text-center fw-bold course-marks-input\" ' +\n");
      out.write("                            'data-course-id=\"' + r.courseId + '\" ' +\n");
      out.write("                            'data-credits=\"' + credits + '\" ' +\n");
      out.write("                            'value=\"' + (hasMarks ? marks : '') + '\" placeholder=\"Enter marks\">';\n");
      out.write("                    } else {\n");
      out.write("                        marksHtml = '<span class=\"fw-bold fs-6 text-dark\">' + (hasMarks ? marks : '<span class=\"text-muted\">-</span>') + '</span>';\n");
      out.write("                    }\n");
      out.write("\n");
      out.write("                    let statusBadge = '';\n");
      out.write("                    if (isPub) {\n");
      out.write("                        statusBadge = '<span class=\"badge bg-success-subtle text-success border border-success-subtle\"><i class=\"bi bi-check-circle me-1\"></i>Published</span>';\n");
      out.write("                    } else if (isEvaluated) {\n");
      out.write("                        statusBadge = '<span class=\"badge bg-warning-subtle text-warning-emphasis border border-warning-subtle\"><i class=\"bi bi-clock me-1\"></i>Unpublished</span>';\n");
      out.write("                    } else {\n");
      out.write("                        statusBadge = '<span class=\"badge badge-unevaluated\"><i class=\"bi bi-dash-circle me-1\"></i>Not Evaluated</span>';\n");
      out.write("                    }\n");
      out.write("\n");
      out.write("                    let actionHtml = '';\n");
      out.write("                    if (canEdit) {\n");
      out.write("                        if (isEvaluated) {\n");
      out.write("                            if (isPub) {\n");
      out.write("                                actionHtml = '<button type=\"button\" class=\"btn btn-xs btn-outline-warning btn-single-publish\" data-course-id=\"' + r.courseId + '\" data-publish=\"false\" title=\"Unpublish this course\"><i class=\"bi bi-eye-slash me-1\"></i>Unpublish</button>';\n");
      out.write("                            } else {\n");
      out.write("                                actionHtml = '<button type=\"button\" class=\"btn btn-xs btn-outline-success btn-single-publish\" data-course-id=\"' + r.courseId + '\" data-publish=\"true\" title=\"Publish this course\"><i class=\"bi bi-send-check me-1\"></i>Publish</button>';\n");
      out.write("                            }\n");
      out.write("                        } else {\n");
      out.write("                            actionHtml = '<button type=\"button\" class=\"btn btn-xs btn-light text-muted border btn-single-publish-disabled\" disabled title=\"Enter marks first to publish\"><i class=\"bi bi-lock me-1\"></i>Publish</button>';\n");
      out.write("                        }\n");
      out.write("                    }\n");
      out.write("\n");
      out.write("                    let semElement = '';\n");
      out.write("                    if (canEdit) {\n");
      out.write("                        let semOpts = '';\n");
      out.write("                        availableSemestersList.forEach(function (s) {\n");
      out.write("                            semOpts += '<option value=\"' + s + '\" ' + (s === courseSem ? 'selected' : '') + '>' + s + '</option>';\n");
      out.write("                        });\n");
      out.write("                        semElement = '<select class=\"form-select form-select-xs course-row-semester-select d-inline-block border text-secondary fw-semibold font-monospace me-1\" style=\"width: auto; max-width: 140px; font-size: 0.72rem; padding: 0.1rem 0.35rem; height: 24px; vertical-align: middle;\" data-course-id=\"' + r.courseId + '\" title=\"Edit semester for this course\">' + semOpts + '</select>';\n");
      out.write("                    } else {\n");
      out.write("                        semElement = courseSem ? ('<span class=\"badge bg-light text-secondary border me-1 small font-monospace\">' + escapeHtml(courseSem) + '</span>') : '';\n");
      out.write("                    }\n");
      out.write("\n");
      out.write("                    const enrolledInfo = '<div class=\"d-flex align-items-center flex-wrap gap-1 mt-1 font-monospace\" style=\"font-size:0.75rem;\">' +\n");
      out.write("                        semElement +\n");
      out.write("                        (r.enrolledBy ? ('<span class=\"text-muted small\">Enrolled by ' + escapeHtml(r.enrolledBy) + '</span>') : '') +\n");
      out.write("                        '</div>';\n");
      out.write("\n");
      out.write("                    const row = '<tr id=\"course-row-' + r.courseId + '\" ' +\n");
      out.write("                        'data-course-id=\"' + r.courseId + '\" ' +\n");
      out.write("                        'data-credits=\"' + credits + '\" ' +\n");
      out.write("                        'data-marks=\"' + (hasMarks ? marks : '') + '\" ' +\n");
      out.write("                        'data-evaluated=\"' + (isEvaluated ? 'true' : 'false') + '\" ' +\n");
      out.write("                        'data-published=\"' + (isPub ? 'true' : 'false') + '\" ' +\n");
      out.write("                        'data-semester=\"' + escapeHtml(courseSem) + '\" ' +\n");
      out.write("                        'data-code=\"' + escapeHtml(r.courseCode).toLowerCase() + '\" ' +\n");
      out.write("                        'data-name=\"' + escapeHtml(r.courseName).toLowerCase() + '\">' +\n");
      out.write("                        '<td class=\"text-muted\">' + (index + 1) + '</td>' +\n");
      out.write("                        '<td><span class=\"font-monospace fw-semibold text-primary\">' + escapeHtml(r.courseCode) + '</span></td>' +\n");
      out.write("                        '<td><div class=\"fw-medium text-dark\">' + escapeHtml(r.courseName) + '</div>' + enrolledInfo + '</td>' +\n");
      out.write("                        '<td class=\"text-center font-monospace\">' + credits.toFixed(1) + '</td>' +\n");
      out.write("                        '<td class=\"text-center\" style=\"max-width: 140px;\">' + marksHtml + '</td>' +\n");
      out.write("                        '<td class=\"text-center font-monospace fw-bold grade-point-cell\">' + (hasMarks ? gp.toFixed(2) : '<span class=\"text-muted\">-</span>') + '</td>' +\n");
      out.write("                        '<td class=\"text-center\"><span class=\"' + badgeClass + ' letter-grade-badge\">' + letter + '</span></td>' +\n");
      out.write("                        '<td class=\"text-center status-cell\">' + statusBadge + '</td>' +\n");
      out.write("                        (canEdit ? ('<td class=\"text-center action-cell\">' + actionHtml + '</td>') : '') +\n");
      out.write("                        '</tr>';\n");
      out.write("                    $tbody.append(row);\n");
      out.write("                });\n");
      out.write("\n");
      out.write("                $('#countFilterAll').text(results.length);\n");
      out.write("                $('#countFilterEvaluated').text(evaluatedCount);\n");
      out.write("                $('#countFilterEmpty').text(unevaluatedCount);\n");
      out.write("\n");
      out.write("                $('#footerTotalCourses').text(results.length);\n");
      out.write("                $('#footerEvaluatedCourses').text(evaluatedCount);\n");
      out.write("                $('#footerTotalCredits').text(totalCredits.toFixed(1));\n");
      out.write("\n");
      out.write("                const calculatedCgpa = totalCredits > 0 ? (weightedPoints / totalCredits).toFixed(2) : '0.00';\n");
      out.write("                $('#modalCgpaDisplay').text(calculatedCgpa);\n");
      out.write("                $('#footerCgpa').text(calculatedCgpa);\n");
      out.write("                $('#modalEvaluatedCount').text(evaluatedCount + ' Evaluated Courses (' + totalCredits.toFixed(1) + ' Credits)');\n");
      out.write("\n");
      out.write("                filterResultsTableRows();\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            function filterResultsTableRows() {\n");
      out.write("                const search = ($('#modalCourseSearch').val() || '').toLowerCase().trim();\n");
      out.write("                const semFilter = ($('#modalCourseSemesterFilter').val() || 'ALL').toUpperCase();\n");
      out.write("\n");
      out.write("                let visibleCount = 0;\n");
      out.write("                let semCredits = 0;\n");
      out.write("                let semPoints = 0;\n");
      out.write("                let semEvalCount = 0;\n");
      out.write("                let semUnevalCount = 0;\n");
      out.write("                let semTotalCount = 0;\n");
      out.write("\n");
      out.write("                $('#resultsTableBody tr').each(function () {\n");
      out.write("                    if ($(this).attr('id') === 'modalNoSemesterMatchRow') return;\n");
      out.write("\n");
      out.write("                    const isEvaluated = ($(this).attr('data-evaluated') === 'true');\n");
      out.write("                    const isPublished = ($(this).attr('data-published') === 'true');\n");
      out.write("                    const code = $(this).attr('data-code') || '';\n");
      out.write("                    const name = $(this).attr('data-name') || '';\n");
      out.write("                    const rowSem = ($(this).attr('data-semester') || '').toString().trim().toUpperCase();\n");
      out.write("                    const credits = parseFloat($(this).data('credits')) || 3.0;\n");
      out.write("                    const marks = parseFloat($(this).attr('data-marks'));\n");
      out.write("\n");
      out.write("                    const matchSem = (semFilter === 'ALL') || (rowSem === semFilter);\n");
      out.write("\n");
      out.write("                    if (matchSem) {\n");
      out.write("                        semTotalCount++;\n");
      out.write("                        if (isEvaluated && !isNaN(marks) && marks >= 0) {\n");
      out.write("                            semEvalCount++;\n");
      out.write("                            semCredits += credits;\n");
      out.write("                            semPoints += (getGradePoint(marks) * credits);\n");
      out.write("                        } else {\n");
      out.write("                            semUnevalCount++;\n");
      out.write("                        }\n");
      out.write("                    }\n");
      out.write("\n");
      out.write("                    let matchFilter = true;\n");
      out.write("                    if (activeResultsFilter === 'evaluated') {\n");
      out.write("                        matchFilter = isEvaluated;\n");
      out.write("                    } else if (activeResultsFilter === 'unevaluated') {\n");
      out.write("                        matchFilter = !isEvaluated;\n");
      out.write("                    }\n");
      out.write("\n");
      out.write("                    const matchSearch = !search || code.includes(search) || name.includes(search);\n");
      out.write("\n");
      out.write("                    if (matchFilter && matchSearch && matchSem) {\n");
      out.write("                        $(this).show();\n");
      out.write("                        visibleCount++;\n");
      out.write("                    } else {\n");
      out.write("                        $(this).hide();\n");
      out.write("                    }\n");
      out.write("                });\n");
      out.write("\n");
      out.write("                $('#countFilterAll').text(semTotalCount);\n");
