      out.write("                    $row.find('.action-cell').html('<button type=\"button\" class=\"btn btn-xs btn-light text-muted border btn-single-publish-disabled\" disabled title=\"Enter marks first to publish\"><i class=\"bi bi-lock me-1\"></i>Publish</button>');\n");
