      out.write("            function saveResults() {\n");
      out.write("                if (!currentResultsStudentUid && !currentResultsStudentId) {\n");
      out.write("                    showToast('danger', 'Student record not found. Please reload.');\n");
      out.write("                    return;\n");
      out.write("                }\n");
      out.write("\n");
      out.write("                const payloadResults = [];\n");
      out.write("                let hasInvalid = false;\n");
      out.write("                const studentJoiningSem = $('#modalStudentSem').text() || 'FALL 2025';\n");
      out.write("\n");
      out.write("                $('#resultsTableBody tr').each(function () {\n");
      out.write("                    const courseId = parseInt($(this).data('course-id'));\n");
      out.write("                    if (!courseId) return;\n");
      out.write("                    const val = $(this).find('.course-marks-input').val();\n");
      out.write("                    const courseRowSem = $(this).find('.course-row-semester-select').val() || $(this).attr('data-semester') || studentJoiningSem;\n");
      out.write("\n");
      out.write("                    if (val !== undefined && val !== '' && !isNaN(parseFloat(val))) {\n");
      out.write("                        const marks = parseFloat(val);\n");
      out.write("                        if (marks < 0 || marks > 100) {\n");
      out.write("                            hasInvalid = true;\n");
      out.write("                        }\n");
      out.write("                        payloadResults.push({\n");
      out.write("                            courseId: courseId,\n");
      out.write("                            marks: marks,\n");
      out.write("                            evaluated: true,\n");
      out.write("                            published: true,\n");
      out.write("                            semester: courseRowSem\n");
      out.write("                        });\n");
      out.write("                    }\n");
      out.write("                });\n");
      out.write("\n");
      out.write("                if (hasInvalid) {\n");
      out.write("                    showToast('danger', 'Please enter valid marks between 0 and 100.');\n");
      out.write("                    return;\n");
      out.write("                }\n");
      out.write("\n");
      out.write("                if (payloadResults.length === 0) {\n");
      out.write("                    showToast('danger', 'No marks entered. Please enter marks (0–100) for at least one course before publishing.');\n");
      out.write("                    return;\n");
      out.write("                }\n");
      out.write("\n");
      out.write("                const $btn = $('#btnPublishResults');\n");
      out.write("                const originalText = $btn.html();\n");
      out.write("                $btn.prop('disabled', true).html('<span class=\"spinner-border spinner-border-sm me-1\"></span> Publishing...');\n");
      out.write("\n");
      out.write("                $.ajax({\n");
      out.write("                    url: contextPath + '/api/students',\n");
      out.write("                    type: 'POST',\n");
      out.write("                    contentType: 'application/json; charset=UTF-8',\n");
      out.write("                    data: JSON.stringify({\n");
      out.write("                        action: 'save_results',\n");
      out.write("                        id: currentResultsStudentId,\n");
      out.write("                        uid: currentResultsStudentUid,\n");
      out.write("                        publish: true,\n");
      out.write("                        results: payloadResults\n");
      out.write("                    }),\n");
      out.write("                    headers: { 'X-Requested-With': 'XMLHttpRequest' },\n");
      out.write("                    success: function (res) {\n");
      out.write("                        if (res.success) {\n");
      out.write("                            showToast('success', res.message || 'Results published successfully and CGPA updated!');\n");
      out.write("                            const newCgpa = parseFloat(res.calculatedCgpa).toFixed(2);\n");
      out.write("                            $('#modalCgpaDisplay').text(newCgpa);\n");
      out.write("                            $('#footerCgpa').text(newCgpa);\n");
      out.write("\n");
      out.write("                            const $studentRow = $('#student-row-' + currentResultsStudentUid);\n");
      out.write("                            if ($studentRow.length > 0) {\n");
      out.write("                                $studentRow.find('.badge-cgpa').text(newCgpa);\n");
      out.write("                            }\n");
      out.write("\n");
      out.write("                            reloadResultsModal();\n");
      out.write("\n");
      out.write("                            if (typeof fetchStatsOnly === 'function') {\n");
      out.write("                                fetchStatsOnly();\n");
      out.write("                            }\n");
      out.write("                        } else {\n");
      out.write("                            showToast('danger', res.message || 'Failed to publish results.');\n");
      out.write("                        }\n");
      out.write("                    },\n");
      out.write("                    error: function (xhr) {\n");
      out.write("                        let errorMsg = 'Failed to publish results.';\n");
      out.write("                        try {\n");
      out.write("                            const data = JSON.parse(xhr.responseText);\n");
      out.write("                            if (data.message) errorMsg = data.message;\n");
      out.write("                        } catch (e) { }\n");
      out.write("                        showToast('danger', errorMsg);\n");
      out.write("                    },\n");
      out.write("                    complete: function () {\n");
      out.write("                        $btn.prop('disabled', false).html(originalText);\n");
      out.write("                    }\n");
      out.write("                });\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            $('#btnPublishResults').on('click', function (e) {\n");
      out.write("                e.preventDefault();\n");
      out.write("                saveResults();\n");
      out.write("            });\n");
      out.write("\n");
      out.write("            // Single Course Publish / Unpublish Toggle\n");
