      out.write("            // ==================== Admin Course Assignment Modal ====================\n");
      out.write("            if (isAdmin) {\n");
      out.write("                let deptCoursesCache = {};\n");
      out.write("\n");
      out.write("                function loadDeptCoursesForAssignment(dept) {\n");
      out.write("                    const $container = $('#assignCoursesListContainer');\n");
      out.write("                    $container.html('<div class=\"text-center py-4\"><div class=\"spinner-border spinner-border-sm text-primary\"></div><span class=\"ms-2 small text-muted\">Loading ' + escapeHtml(dept) + ' curriculum courses...</span></div>');\n");
      out.write("\n");
      out.write("                    $.ajax({\n");
      out.write("                        url: contextPath + '/api/students',\n");
      out.write("                        type: 'POST',\n");
      out.write("                        contentType: 'application/json; charset=UTF-8',\n");
      out.write("                        data: JSON.stringify({ action: 'courses', department: dept }),\n");
      out.write("                        headers: { 'X-Requested-With': 'XMLHttpRequest' },\n");
      out.write("                        success: function (res) {\n");
      out.write("                            if (res.success && res.courses) {\n");
      out.write("                                deptCoursesCache[dept] = res.courses;\n");
      out.write("                                renderAssignCourseCheckboxes(res.courses);\n");
